// Package udiff computes and renders unified diffs between two texts.
package udiff

import (
	"io"

	"github.com/pmezard/go-difflib/difflib"
)

// DefaultContext is the number of unchanged lines shown around each change
// when Options.Context is not set.
const DefaultContext = 3

// Options controls how a unified diff is rendered. A nil *Options is valid
// and uses the defaults: FromFile "a", ToFile "b" and DefaultContext.
type Options struct {
	// FromFile and ToFile are the labels used in the "---" and "+++" headers.
	FromFile string
	ToFile   string
	// Context is the number of context lines; values <= 0 use DefaultContext.
	Context int
}

func (o *Options) normalize() (from, to string, context int) {
	from, to, context = "a", "b", DefaultContext
	if o == nil {
		return from, to, context
	}
	if o.FromFile != "" {
		from = o.FromFile
	}
	if o.ToFile != "" {
		to = o.ToFile
	}
	if o.Context > 0 {
		context = o.Context
	}
	return from, to, context
}

// Unified returns the unified diff between a and b. It returns an empty
// string when a and b are identical.
func Unified(a, b string, opts *Options) (string, error) {
	from, to, context := opts.normalize()
	return difflib.GetUnifiedDiffString(difflib.UnifiedDiff{
		A:        difflib.SplitLines(a),
		B:        difflib.SplitLines(b),
		FromFile: from,
		ToFile:   to,
		Context:  context,
	})
}

// WriteUnified writes the unified diff between a and b to w. It reports the
// number of bytes written and writes nothing when a and b are identical.
func WriteUnified(w io.Writer, a, b string, opts *Options) (int, error) {
	s, err := Unified(a, b, opts)
	if err != nil {
		return 0, err
	}
	if s == "" {
		return 0, nil
	}
	return io.WriteString(w, s)
}

package udiff

import (
	"bytes"
	"strings"
	"testing"
)

func TestUnifiedIdentical(t *testing.T) {
	got, err := Unified("same\nlines\n", "same\nlines\n", nil)
	if err != nil {
		t.Fatalf("Unified: %v", err)
	}
	if got != "" {
		t.Fatalf("Unified identical = %q, want empty", got)
	}
}

func TestUnifiedChange(t *testing.T) {
	got, err := Unified("a\nb\nc\n", "a\nB\nc\n", &Options{
		FromFile: "old.txt",
		ToFile:   "new.txt",
		Context:  1,
	})
	if err != nil {
		t.Fatalf("Unified: %v", err)
	}
	for _, want := range []string{
		"--- old.txt\n",
		"+++ new.txt\n",
		"@@ -1,3 +1,3 @@\n",
		" a\n",
		"-b\n",
		"+B\n",
		" c\n",
	} {
		if !strings.Contains(got, want) {
			t.Errorf("diff missing %q:\n%s", want, got)
		}
	}
}

func TestUnifiedDefaults(t *testing.T) {
	got, err := Unified("x\n", "y\n", nil)
	if err != nil {
		t.Fatalf("Unified: %v", err)
	}
	if !strings.HasPrefix(got, "--- a\n+++ b\n") {
		t.Errorf("default labels missing:\n%s", got)
	}
}

func TestWriteUnified(t *testing.T) {
	var changed bytes.Buffer
	n, err := WriteUnified(&changed, "a\n", "b\n", nil)
	if err != nil {
		t.Fatalf("WriteUnified: %v", err)
	}
	if n == 0 || changed.Len() != n {
		t.Errorf("WriteUnified wrote %d bytes, buffer has %d", n, changed.Len())
	}

	var same bytes.Buffer
	if n, err := WriteUnified(&same, "a\n", "a\n", nil); err != nil || n != 0 || same.Len() != 0 {
		t.Errorf("WriteUnified on identical = (%d, %v), buffer %q; want (0, nil, \"\")", n, err, same.String())
	}
}

// Command difftool prints the unified diff between two files.
//
// Usage: difftool [-context n] <from> <to>
//
// It exits 0 when the files are identical, 1 when they differ and 2 on error.
package main

import (
	"flag"
	"fmt"
	"os"

	"example.com/difftool/udiff"
)

func main() {
	context := flag.Int("context", udiff.DefaultContext, "number of context lines")
	flag.Usage = func() {
		fmt.Fprintf(flag.CommandLine.Output(), "usage: difftool [-context n] <from> <to>\n")
		flag.PrintDefaults()
	}
	flag.Parse()

	if flag.NArg() != 2 {
		flag.Usage()
		os.Exit(2)
	}

	fromPath, toPath := flag.Arg(0), flag.Arg(1)
	a, err := os.ReadFile(fromPath)
	if err != nil {
		fmt.Fprintln(os.Stderr, "difftool:", err)
		os.Exit(2)
	}
	b, err := os.ReadFile(toPath)
	if err != nil {
		fmt.Fprintln(os.Stderr, "difftool:", err)
		os.Exit(2)
	}

	diff, err := udiff.Unified(string(a), string(b), &udiff.Options{
		FromFile: fromPath,
		ToFile:   toPath,
		Context:  *context,
	})
	if err != nil {
		fmt.Fprintln(os.Stderr, "difftool:", err)
		os.Exit(2)
	}

	if diff == "" {
		return
	}
	fmt.Print(diff)
	os.Exit(1)
}
